// Loop through all incoming items
for (const item of items) {
  const body = item.json.body || {};
  const message = body.message || {};
  const sender = message.sender || {};
  const conversation = body.conversation || {};
  const account = body.account || {};

  // 1. Instagram: use participantId as unique identifier (no phone number)
  const participantId = conversation.participantId || conversation.platformConversationId || '';
  const senderJid = participantId; // Raw Instagram ID, e.g. "1322499536539094"

  // 2. Sender display name (the customer)
  const senderName = conversation.participantName || '';

  // 3. Timestamp — ISO 8601 string, offset to UTC+3
  let formattedTime = '';
  const rawTimestamp = message.sentAt || body.timestamp || '';
  if (rawTimestamp) {
    const date = new Date(rawTimestamp);
    const utc3Date = new Date(date.getTime() + 10800000);
    formattedTime = utc3Date.toISOString().replace('T', ' ').replace('Z', '');
  }

  // 4. Message type
  let msgType = 'text';
  if (message.attachments && message.attachments.length > 0) {
    msgType = message.attachments[0].type || 'media';
  }

  // 5. Media (first attachment URL if any)
  const media = (message.attachments && message.attachments.length > 0)
    ? (message.attachments[0].url || null)
    : null;

  // 6. Output
  item.json = {
    SenderJid:      senderJid,
    SenderName:     senderName,
    Timestamp:      formattedTime,
    MsgType:        msgType,
    Msg:            message.text || '',
    Media:          media,
    Instance:       account.displayName || account.username || '',
    Key:            body.id || '',
    phonenumber:    '',              // Instagram has no phone number
    ConversationId: message.conversationId || conversation.id || '',
    Direction:      message.direction || '',
    Event:          body.event || '',
    AccountId:      account.id || account.accountId || '',
    MessageId:      message.id || ''   // ← "6a4a5e6f9d9472faae8534e6"
  };

}

return items;

